'use strict';
// Each task, explanation step and square variant has its own editable sheet.
const sheets=new Map();let workVariant=0,drawingTool='pointer',draft=null,workingMarks=null,activeSheet=null;
function sheetKey(){return `${task}:${current().step}:${task===0&&current().step===0?workVariant:''}`}
function getSheet(key=sheetKey()){if(!sheets.has(key))sheets.set(key,{marks:[],past:[]});return sheets.get(key)}
function commitMarks(marks,key=sheetKey()){const sheet=getSheet(key);sheet.past.push(sheet.marks);if(sheet.past.length>80)sheet.past.shift();sheet.marks=marks}
function addMark(mark,key=sheetKey()){commitMarks([...getSheet(key).marks,mark],key)}
function undoDrawing(){finishMark();const sheet=getSheet();if(sheet.past.length)sheet.marks=sheet.past.pop();renderWorkspace()}
function clearDrawing(){finishMark();if(getSheet().marks.length)commitMarks([]);renderWorkspace()}
function squareWorkScene(){let out='';for(let y=0;y<4;y++)for(let x=0;x<4;x++)out+=`<rect x="${210+x*48}" y="${20+y*48}" width="48" height="48" fill="#fffefa" stroke="#b7c8be"/>`;out+=`<path d="${CUTS[workVariant]}" transform="translate(210 20) scale(48)" class="cut"/>`+text(306,265,`Твоя схема · рисунок ${LETTERS[workVariant]}`);return svg(out,`Рисунок ${LETTERS[workVariant]}: можно самостоятельно закрашивать клетки`)}
function drawingGrid(){const step=current().step;if(task===0){if(step===0||step===2||(step===3&&current().frame===0))return{x:210,y:20,dx:48,dy:48,cols:4,rows:4};if(step===1)return{x:200,y:20,dx:53,dy:53,cols:4,rows:4}}if(task===2)return{x:102,y:15,dx:62,dy:58,cols:7,rows:4};if(task===7)return{x:110,y:4,dx:36,dy:34,cols:11,rows:8};return null}
function cellAt(point,grid=drawingGrid()){if(!grid)return null;const col=Math.floor((point[0]-grid.x)/grid.dx),row=Math.floor((point[1]-grid.y)/grid.dy);if(col<0||row<0||col>=grid.cols||row>=grid.rows)return null;return[grid.x+col*grid.dx,grid.y+row*grid.dy,grid.dx,grid.dy]}
function ladderGeometry(a,b){const length=Math.hypot(b[0]-a[0],b[1]-a[1]);if(length<1)return{rails:[],rungs:[]};const normal=[-(b[1]-a[1])/length*8,(b[0]-a[0])/length*8],offset=(p,sign)=>[p[0]+normal[0]*sign,p[1]+normal[1]*sign];const rails=[[offset(a,-1),offset(b,-1)],[offset(a,1),offset(b,1)]],rungs=[];const count=Math.max(1,Math.floor(length/16));for(let i=0;i<=count;i++){const t=i/count,p=[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];rungs.push([offset(p,-1),offset(p,1)])}return{rails,rungs}}
function markMarkup(mark){const color=mark.color,points=mark.points||[];if(mark.type==='fill')return mark.cells.map(([x,y,w,h])=>`<rect x="${x+1}" y="${y+1}" width="${w-2}" height="${h-2}" fill="${color}" fill-opacity=".4"/>`).join('');if(!points.length)return'';if(mark.type==='ladder'){const lines=ladderGeometry(points[0],points.at(-1));return [...lines.rails,...lines.rungs].map(([a,b])=>`<path d="M${a.join(' ')}L${b.join(' ')}" stroke="${color}" stroke-width="3" fill="none" stroke-linecap="round"/>`).join('')}if(points.length===1)return `<circle cx="${points[0][0]}" cy="${points[0][1]}" r="2" fill="${color}"/>`;return `<polyline points="${points.map(p=>p.join(',')).join(' ')}" stroke="${color}" stroke-width="4" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`}
function pointSegmentDistance(p,a,b){const dx=b[0]-a[0],dy=b[1]-a[1],d=dx*dx+dy*dy,t=d?Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/d)):0;return Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy)}
function markHit(mark,p){if(mark.type==='fill')return mark.cells.some(([x,y,w,h])=>p[0]>=x&&p[0]<=x+w&&p[1]>=y&&p[1]<=y+h);const points=mark.points||[];return points.some((a,i)=>pointSegmentDistance(p,a,points[i+1]||a)<(mark.type==='ladder'?18:12))}
function renderWorkspace(){const grid=drawingGrid();if(drawingTool==='fill'&&!grid)drawingTool='pointer';const sheet=getSheet(),marks=workingMarks&&activeSheet===sheetKey()?workingMarks:sheet.marks;const preview=draft&&activeSheet===sheetKey()?[...marks,draft]:marks;$('drawingLayer').innerHTML=preview.map(markMarkup).join('');$('drawingLayer').setAttribute('data-tool',drawingTool);$('drawingLayer').setAttribute('aria-label',`Твои пометки: ${sheet.marks.length}. ${drawingTool==='pointer'?'Выбери инструмент для рисования.':'Рисование поверх схемы.'}`);$('undoDrawing').disabled=!sheet.past.length;$('clearDrawing').disabled=!sheet.marks.length;$('variantLabel').hidden=!(task===0&&current().step===0);$('workVariant').selectedIndex=workVariant;
if(typeof document.querySelectorAll==='function')for(const button of document.querySelectorAll('[data-tool]')){button.setAttribute('aria-pressed',String(button.dataset.tool===drawingTool));if(button.dataset.tool==='fill')button.disabled=!grid}
$('drawingHint').textContent=playing?'Чтобы рисовать, поставь показ на паузу':drawingTool==='fill'?'Веди по клеткам, чтобы закрашивать их':drawingTool==='ladder'?'Потяни от начала к концу лестницы':drawingTool==='eraser'?'Проведи по пометке, чтобы стереть её':drawingTool==='pointer'?'Выбери инструмент. Пометки сохраняются для каждого шага.':'Рисуй на схеме пальцем или мышью';}
function finishMark(){if(activeSheet===null)return;if(workingMarks!==null)commitMarks(workingMarks,activeSheet);else if(draft&&(draft.type==='fill'?draft.cells.length:draft.points.length)&&(draft.type!=='ladder'||Math.hypot(draft.points.at(-1)[0]-draft.points[0][0],draft.points.at(-1)[1]-draft.points[0][1])>=8))addMark(draft,activeSheet);draft=null;workingMarks=null;activeSheet=null;renderWorkspace()}
function pointerPoint(event){const layer=$('drawingLayer'),point=layer.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const matrix=layer.getScreenCTM();if(!matrix)return null;const p=point.matrixTransform(matrix.inverse());return[Math.max(0,Math.min(640,p.x)),Math.max(0,Math.min(300,p.y))]}
function extendMark(point){if(workingMarks!==null){workingMarks=workingMarks.flatMap(mark=>{if(mark.type!=='fill')return markHit(mark,point)?[]:[mark];const cells=mark.cells.filter(([x,y,w,h])=>!(point[0]>=x&&point[0]<x+w&&point[1]>=y&&point[1]<y+h));return cells.length?[{...mark,cells}]:[]})}else if(draft?.type==='fill'){const from=draft.lastPoint||point,grid=drawingGrid(),steps=Math.max(1,Math.ceil(Math.hypot(point[0]-from[0],point[1]-from[1])/((grid?Math.min(grid.dx,grid.dy):30)/3)));for(let i=0;i<=steps;i++){const t=i/steps,cell=cellAt([from[0]+(point[0]-from[0])*t,from[1]+(point[1]-from[1])*t]);if(cell&&!draft.cells.some(c=>c[0]===cell[0]&&c[1]===cell[1]))draft.cells.push(cell)}draft.lastPoint=point}else if(draft?.type==='pen'){const last=draft.points.at(-1);if(Math.hypot(point[0]-last[0],point[1]-last[1])>=2)draft.points.push(point)}else if(draft)draft.points=[draft.points[0],point];renderWorkspace()}
function setupWorkspace(){const layer=$('drawingLayer');$('drawingTools').addEventListener('click',event=>{const button=event.target.closest('[data-tool]');if(!button||button.disabled)return;finishMark();pause();drawingTool=button.dataset.tool;renderWorkspace()});$('workVariant').addEventListener('change',()=>{finishMark();pause();workVariant=$('workVariant').selectedIndex;renderScene();renderWorkspace()});$('drawingColor').addEventListener('input',()=>{finishMark();pause()});$('undoDrawing').onclick=()=>{pause();undoDrawing()};$('clearDrawing').onclick=()=>{pause();clearDrawing()};
layer.addEventListener('pointerdown',event=>{if(drawingTool==='pointer'||event.button>0)return;event.preventDefault();finishMark();pause();const p=pointerPoint(event);if(!p)return;activeSheet=sheetKey();if(drawingTool==='eraser')workingMarks=getSheet().marks.slice();else draft={type:drawingTool,color:$('drawingColor').value,points:[p],cells:[]};layer.setPointerCapture(event.pointerId);extendMark(p)});layer.addEventListener('pointermove',event=>{if(activeSheet===null)return;event.preventDefault();const p=pointerPoint(event);if(p)extendMark(p)});layer.addEventListener('pointerup',finishMark);layer.addEventListener('pointercancel',finishMark);layer.addEventListener('lostpointercapture',finishMark)}
